def f(g):
    H,W=len(g),len(g[0])
    # separator row: mostly 3s? in demo cells are 5s; separators rows have few 5s. General: sep lines form lattice.
    # Determine sep rows: rows that differ from majority pattern of columns? Use column-mode: sep rows are those where the set of values equals union pattern... 
    # Robust: a separator cell value is a color c (the line color, most common overall). A sep row = row where most cells are the line color OR marker colors (non-background-cell-color?).
    # In demo: cell interior color =5, line color=3. Sep rows have few 5s. Sep cols have few 5s? col1 mostly 3 -> yes sep. col8 mostly 3 except markers. col16 all 3. So sep cols = cols with few 5s? col 1,8,15,22 have <~7 5s among 28; others many. Good.
    sr=[r for r in range(H) if sum(1 for x in g[r] if x==5)<W*0.7]
    sc=[c for c in range(W) if sum(1 for x in [g[r][c] for r in range(H)] if x==5)<H*0.7]
    out=[[5]*len(sc) for _ in range(len(sr))]
    for i,r in enumerate(sr):
        for j,c in enumerate(sc):
            corners={(x,y) for x in (r-1,r+1) for y in (c-1,c+1)} & {(x,y) for x in range(H) for y in range(W)}
            vals={g[x][y] for x,y in corners}
            val=list(vals)[0] if len(vals)==1 else None
            # check all four same and not background-ish: use value that's neither line color nor 5
            if len(vals)==1 and val!=5:
                out[i][j]=val
    return out
